"""Small synthetic videos for the probe tests, generated by ffmpeg (nothing is read from a real library)."""

from __future__ import annotations

import shutil
import subprocess
from pathlib import Path

import pytest

NEEDS_FFMPEG = pytest.mark.skipif(
    shutil.which("ffmpeg") is None or shutil.which("ffprobe") is None,
    reason="ffmpeg and ffprobe are required",
)


def _ffmpeg(*args: str) -> None:
    subprocess.run(["ffmpeg", "-hide_banner", "-loglevel", "error", "-y", *args], check=True)


def _testsrc(size: str, seconds: int = 2, rate: int = 25) -> list[str]:
    return ["-f", "lavfi", "-i", f"testsrc2=size={size}:rate={rate}:duration={seconds}"]


@pytest.fixture(scope="session")
def media(tmp_path_factory: pytest.TempPathFactory) -> dict[str, Path]:
    d = tmp_path_factory.mktemp("media")
    out: dict[str, Path] = {}

    out["plain"] = d / "plain.mp4"
    _ffmpeg(*_testsrc("320x180"), "-c:v", "libx264", "-pix_fmt", "yuv420p", str(out["plain"]))

    _ffmpeg("-f", "lavfi", "-i", "color=c=red:s=64x64", "-frames:v", "1", str(d / "cover.png"))
    out["cover"] = d / "with_cover.mp4"
    _ffmpeg(
        "-i",
        str(out["plain"]),
        "-i",
        str(d / "cover.png"),
        "-map",
        "0:v",
        "-map",
        "1:v",
        "-c",
        "copy",
        "-disposition:v:1",
        "attached_pic",
        str(out["cover"]),
    )

    out["nonsquare"] = d / "nonsquare.mp4"
    _ffmpeg(
        *_testsrc("320x180"),
        "-vf",
        "scale=160:120,setsar=32/27",
        "-c:v",
        "libx264",
        "-pix_fmt",
        "yuv420p",
        str(out["nonsquare"]),
    )

    out["offset"] = d / "offset.mkv"
    _ffmpeg(
        *_testsrc("320x180"),
        "-c:v",
        "libx264",
        "-bf",
        "0",
        "-pix_fmt",
        "yuv420p",
        "-output_ts_offset",
        "5",
        str(out["offset"]),
    )

    for name, transfer in (("hdr10", "smpte2084"), ("hlg", "arib-std-b67")):
        out[name] = d / f"{name}.mp4"
        # setparams is needed: the test source's own colour tags would override the encoder flags
        _ffmpeg(
            *_testsrc("320x180", seconds=1),
            "-vf",
            f"setparams=color_primaries=bt2020:color_trc={transfer}:colorspace=bt2020nc",
            "-c:v",
            "libx265",
            "-pix_fmt",
            "yuv420p10le",
            "-color_primaries",
            "bt2020",
            "-color_trc",
            transfer,
            "-colorspace",
            "bt2020nc",
            "-x265-params",
            "log-level=error",
            str(out[name]),
        )

    out["audio_only"] = d / "audio_only.mp4"
    _ffmpeg("-f", "lavfi", "-i", "sine=duration=1", "-c:a", "aac", str(out["audio_only"]))

    out["corrupt"] = d / "corrupt.mkv"
    out["corrupt"].write_bytes(bytes(range(256)) * 64)

    out["unicode"] = d / "Café – 日本語 (2020).mp4"
    shutil.copy(out["plain"], out["unicode"])

    out["interlaced"] = d / "interlaced.mp4"
    _ffmpeg(
        *_testsrc("320x180"),
        "-vf",
        "interlace=scan=tff",
        "-flags",
        "+ilme+ildct",
        "-c:v",
        "libx264",
        "-pix_fmt",
        "yuv420p",
        str(out["interlaced"]),
    )
    return out
